 "beauty-faq-en": {
  "faqGroups": [
   {
    "title": "الأساسيات — ماذا يفعل التحليل الوراثي للجلد",
    "items": [
     {
      "q": "ما هو التحليل الوراثي للجلد (DNAbeauty Control)؟",
      "a": "تحليل لجيناتك يركّز على المجالات ذات الصلة بالجلد: تحلّل الكولاجين، والحساسية للأشعة فوق البنفسجية، والتصبّغ، وترطيب الجلد، والدفاع المضاد للأكسدة، والميل إلى الالتهاب. ومن مجموعة بيانات حمضك النووي، يُقيَّم أكثر من 20 متغيراً جينياً ذا صلة بالجلد وتُترجم النتائج إلى توصيات عملية للعناية والحماية."
     },
     {
      "q": "ما الفرق عن التحليل التجميلي للبشرة؟",
      "a": "تقيس التحاليل التجميلية للبشرة حالتها الراهنة — الترطيب، والزهم، والتصبّغ وغيرها — وتتفاعل معها. أما التحليل الوراثي للجلد فيُظهر لك أي الخصائص ونقاط الضعف مثبّتة بشكل دائم في جيناتك. وبذلك يمكنك الوقاية بشكل استباقي بدلاً من العلاج التفاعلي عندما تصبح المشكلات مرئية."
     },
     {
      "q": "كم عدد الجينات التي تُحلَّل؟",
      "a": "أكثر من 20 متغيراً جينياً ذا صلة بالجلد. والمجالات الرئيسية: MMP1 (تحلّل الكولاجين، والتجاعيد)، وMC1R (الحساسية للأشعة فوق البنفسجية، والتصبّغ)، وFLG (filaggrin، ترطيب الجلد / وظيفة الحاجز)، وSOD2/CAT/GPX (الدفاع المضاد للأكسدة)، وجينات الالتهاب مثل IL6 وTNF-α."
     },
     {
      "q": "إلى متى تبقى نتيجتي صالحة؟",
      "a": "لا تتغير جيناتك طوال حياتك — لذا تبقى النتائج الأساسية صالحة بشكل دائم. وما يُصقَل هو التقييم نفسه، إذ تُدمج الأبحاث الجديدة باستمرار."
     }
    ]
   },
   {
    "title": "الوراثة وشيخوخة الجلد — فهم النتيجة",
    "items": [
     {
      "q": "ماذا يعني متغيّر MMP1 «النشط»؟",
      "a": "يُحلِّل MMP1 (Matrix Metalloproteinase 1) الكولاجين في الجلد. ويؤدي المتغيّر شديد النشاط وراثياً إلى تحلّل أسرع للكولاجين — فيفقد الجلد تماسكه مبكراً وتتكوّن التجاعيد أسرع. والإجراءات المضادة: حماية ثابتة من الأشعة فوق البنفسجية، ومضادات الأكسدة، والامتناع عن التدخين، وعناية قائمة على الريتينويدات أو الببتيدات."
     },
     {
      "q": "ماذا يخبرني MC1R عن الحساسية للأشعة فوق البنفسجية؟",
      "a": "يتحكم MC1R في إنتاج الإيوميلانين (Eumelanin) (الصبغة الداكنة الواقية من الأشعة فوق البنفسجية) مقابل الفيوميلانين (Pheomelanin) (الصبغة المائلة إلى الحمرة التي تولّد جذوراً حرة تحت الأشعة فوق البنفسجية). أما المتغيرات غير المواتية فتعني: حروق شمس أسرع، وخطراً أعلى للتلف الناتج عن الأشعة فوق البنفسجية ولسرطان الجلد — ما يستلزم انضباطاً أكثر صرامة في استخدام واقي الشمس."
     },
     {
      "q": "لماذا يُعدّ FLG (filaggrin) مهماً لعنايتي بالبشرة؟",
      "a": "يُنتج FLG بروتين filaggrin الذي يُماسك حاجز الجلد الطبيعي ويربط الرطوبة. ومع انخفاض نشاط FLG وراثياً، يصبح حاجز الجلد أضعف — فتُفقد الرطوبة أسرع وتخترقه المهيّجات بسهولة أكبر. التوصية: عناية معزّزة للحاجز (Ceramides، والكوليسترول، والأحماض الدهنية الحرة)، ومنظّفات لطيفة، وتجنّب المواد الخافضة للتوتر السطحي المجفِّفة."
     },
     {
      "q": "هل يؤثر هذا فعلاً على مظهري بشكل قابل للقياس؟",
      "a": "نعم، لكن ليس بين ليلة وضحاها. فنقاط الضعف الوراثية تتراكم عبر السنين. ويمكن لشخصين في العمر نفسه أن يختلفا بيولوجياً بمقدار 10-15 عاماً — تبعاً لمدى نجاحهما في تعويض نقاط الضعف الوراثية بنمط الحياة."
     }
    ]
   },
   {
    "title": "توصيات عملية وتوقعات",
    "items": [
     {
      "q": "بأي سرعة سألاحظ تأثيراً من العناية المخصّصة؟",
      "a": "بعض التأثيرات تظهر خلال أسابيع (الترطيب، والإشراق، والتهيّج)، وأخرى لا تظهر إلا بعد شهور إلى سنوات (تكوّن التجاعيد، والتصبّغ، وبنية الجلد). فالعناية المخصّصة ليست حلاً سريعاً بل استراتيجية حماية طويلة الأمد."
     },
     {
      "q": "هل أحتاج إلى كريمات باهظة الثمن؟",
      "a": "ليس بالضرورة. فالمهم هو المكوّنات الصحيحة لاستعدادك الوراثي — وهي متوفرة في كل فئة سعرية. وما يهم فعلاً: تركيز المادة الفعّالة، والتركيبة، والانتظام في الاستخدام. فيمكن لسيروم فيتامين C ميسور التكلفة أن يتفوق على كريم باهظ خالٍ من المواد الفعّالة."
     },
     {
      "q": "هل نمط حياتي أهم من جيناتي؟",
      "a": "الاثنان يعملان معاً. فالجينات تحدد الإمكانات ونقاط الضعف — ونمط الحياة يقرر إلى أي مدى تعوّض هذه النقاط أو تضخّمها. والقاعدة العامة: مع الاستعداد الوراثي غير المواتي، يصبح نمط الحياة الثابت أكثر أهمية مما هو عليه مع «الجينات المحظوظة»."
     }
    ]
   }
  ]
 },
